export type Ball = { x: number; y: number; vx: number; vy: number; r: number; color: string };

export const W = 400;
export const H = 300;
export const R = 10;
const G = 0.2;

const COLORS = ["#e74c3c", "#3498db", "#2ecc71", "#f1c40f", "#9b59b6", "#e67e22", "#1abc9c", "#34495e"];

function rand(a: number, b: number): number {
  return a + Math.random() * (b - a);
}

export function make(): Ball {
  return {
    x: rand(R, W - R),
    y: rand(R, H - R),
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    r: R,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeMany(n: number): Ball[] {
  return Array.from({ length: n }, () => make());
}

function walls(b: Ball): void {
  if (b.x - b.r < 0) {
    b.x = b.r;
    b.vx = Math.abs(b.vx);
  } else if (b.x + b.r > W) {
    b.x = W - b.r;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y - b.r < 0) {
    b.y = b.r;
    b.vy = Math.abs(b.vy);
  } else if (b.y + b.r > H) {
    b.y = H - b.r;
    b.vy = -Math.abs(b.vy);
  }
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += G;
    b.x += b.vx;
    b.y += b.vy;
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const minD = a.r + b.r;
      const d2 = dx * dx + dy * dy;
      if (d2 < minD * minD) {
        let d = Math.sqrt(d2);
        let nx: number;
        let ny: number;
        if (d === 0) {
          nx = 1;
          ny = 0;
          d = 0;
        } else {
          nx = dx / d;
          ny = dy / d;
        }
        // separar para que no queden superpuestas
        const overlap = (minD - d) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        // intercambiar velocidades si se acercan
        const rel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (rel < 0) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
      }
    }
  }

  for (const b of balls) walls(b);
}

export function draw(canvas: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#fafafa";
  ctx.fillRect(0, 0, W, H);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

