use "./sim.ts" { make, makeMany, step, draw }

page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv
  ref rafId

  fn tick() {
    if !paused {
      step(balls)
      draw(cv, balls)
      frames++
    }
    rafId = requestAnimationFrame(tick)
  }

  fn add() {
    balls = [...balls, make()]
    if paused { draw(cv, balls) }
  }

  fn reset() {
    balls = makeMany(5)
    frames = 0
    if paused { draw(cv, balls) }
  }

  mount {
    balls = makeMany(5)
    rafId = requestAnimationFrame(tick)
    cleanup {
      cancelAnimationFrame(rafId)
    }
  }

  column gap=2 {
    canvas ref=cv id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frames}`
    }
    row gap=2 {
      button "Agregar" primary -> add()
      button paused ? "Reanudar" : "Pausar" -> paused = !paused
      button "Reiniciar" -> reset()
    }
  }
}

