export const W = 400;
export const H = 300;
export const R = 10;
export const GRAVITY = 0.2;

export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
  color: string;
}

const COLORS = ["#e74c3c", "#3498db", "#2ecc71", "#f1c40f", "#9b59b6", "#e67e22", "#1abc9c"];

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function make(existing: Ball[] = []): Ball {
  let x = rand(R, W - R);
  let y = rand(R, H - R);
  for (let tries = 0; tries < 50; tries++) {
    const overlaps = existing.some((b) => Math.hypot(b.x - x, b.y - y) < b.r + R);
    if (!overlaps) break;
    x = rand(R, W - R);
    y = rand(R, H - R);
  }
  let vx = rand(-3, 3);
  let vy = rand(-3, 3);
  if (Math.abs(vx) < 0.5) vx = vx < 0 ? -0.5 : 0.5;
  return {
    x,
    y,
    vx,
    vy,
    r: R,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeMany(n: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(make(balls));
  return balls;
}

function confine(b: Ball): void {
  if (b.x - b.r < 0) {
    b.x = b.r;
    b.vx = Math.abs(b.vx);
  } else if (b.x + b.r > W) {
    b.x = W - b.r;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y - b.r < 0) {
    b.y = b.r;
    b.vy = Math.abs(b.vy);
  } else if (b.y + b.r > H) {
    b.y = H - b.r;
    b.vy = -Math.abs(b.vy);
  }
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;
    confine(b);
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let dist = Math.hypot(dx, dy);
      const minDist = a.r + b.r;
      if (dist < minDist) {
        // colisión elástica (masas iguales): intercambian velocidades
        const tvx = a.vx;
        const tvy = a.vy;
        a.vx = b.vx;
        a.vy = b.vy;
        b.vx = tvx;
        b.vy = tvy;

        // separarlas para que no queden pegadas
        if (dist === 0) {
          dx = 1;
          dy = 0;
          dist = 1;
        }
        const overlap = (minDist - dist) / 2;
        const nx = dx / dist;
        const ny = dy / dist;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        confine(a);
        confine(b);
      }
    }
  }
}

export function draw(cv: HTMLCanvasElement | null | undefined, balls: Ball[]): void {
  if (!cv) return;
  const ctx = cv.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = "#f8f9fa";
  ctx.fillRect(0, 0, cv.width, cv.height);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
    ctx.strokeStyle = "#333";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

